-- 053_scenario_missions.sql: missions in role-play scenarios. Each scenario
-- gets three things the learner sets out to do ("order a drink", "ask for
-- the bill"), shown as a checklist in the conversation; the teacher ticks
-- them as they are done. Written for every published scenario, reviewed for
-- gender-neutral Hebrew. The app works before and after this runs (no
-- column, no missions).

alter table public.conversation_scenarios add column if not exists objectives jsonb;
alter table public.conversations add column if not exists objectives_done smallint[] not null default '{}';

update public.conversation_scenarios set objectives = $j$[{"he":"למסור דרכון ופרטי הזמנה","en":"Give your passport and booking details"},{"he":"לענות על שאלות לגבי מזוודות","en":"Answer questions about luggage"},{"he":"לשאול על שער העלייה למטוס והשעה","en":"Ask about the gate and boarding time"}]$j$::jsonb where slug = 'airport-checkin';
